const fs=require('node:fs');const path=require('node:path');const crypto=require('node:crypto');
const root=process.cwd(), seed=JSON.parse(fs.readFileSync(path.join(root,'vendor','official-programmes.json'),'utf8'));
const output=path.join(root,'data','source-observations.json');const previous=fs.existsSync(output)?JSON.parse(fs.readFileSync(output,'utf8')):{};
const allowed=new Set(['www.uni-saarland.de','corsi.unibo.it','www.unipd.it','datascience.math.unipd.it','www.polimi.it']);
async function run(){const next={...previous};for(const p of seed){const url=new URL(p.source);if(url.protocol!=='https:'||!allowed.has(url.hostname)){console.error('Rejected source',p.id);continue}try{const res=await fetch(url,{signal:AbortSignal.timeout(12000),redirect:'manual',headers:{'User-Agent':'EUnistud source availability check'}});if(!res.ok){next[p.id]={...previous[p.id],lastAttempt:new Date().toISOString(),httpStatus:res.status,error:'Source unavailable; recheck manually'};continue}const body=await res.text();const hash=crypto.createHash('sha256').update(body).digest('hex');const old=previous[p.id]?.hash;next[p.id]={url:p.source,lastAttempt:new Date().toISOString(),httpStatus:res.status,hash,changed:old?hash!==old:null,needsReview:true};console.log(p.id,old?(old===hash?'unchanged':'changed'):'baseline recorded')}catch{next[p.id]={...previous[p.id],lastAttempt:new Date().toISOString(),error:'Source check failed; recheck manually'};console.log(p.id,'unavailable')}}fs.mkdirSync(path.dirname(output),{recursive:true});const tmp=output+'.tmp';fs.writeFileSync(tmp,JSON.stringify(next,null,2));fs.renameSync(tmp,output);console.log('Observations recorded. Automated checks do not verify facts or extend freshness.');}run().catch(e=>{console.error(e.message);process.exitCode=1});
